    std_c = np.std(np.diff(x)) if len(x) > 1 else 1e-12
    std_d = np.std(np.diff(y)) if len(y) > 1 else 1e-12
    if std_c < 1e-12: std_c = abs(x[0]) * 0.01 if abs(x[0]) > 0 else 0.01
    if std_d < 1e-12: std_d = abs(y[0]) * 0.01 if abs(y[0]) > 0 else 0.01
    thresh_c = x[0] + sigma_mult * std_c
    thresh_d = y[0] + sigma_mult * std_d
