    from statsmodels.regression.linear_model import OLS
    from statsmodels.tools import add_constant
    y_ser = orient(d, dn)
    x_ser = orient(c, cn)
    n = len(y_ser)
    if n <= max_lag + 1:
        return {'method':'perm_granger','F_obs':0,'p_value':1.0,'significant':False}
    Y = y_ser[max_lag:]
    X_restricted = np.column_stack([y_ser[max_lag-i-1:n-i-1] for i in range(max_lag)])
    X_full = np.column_stack([X_restricted] + [x_ser[max_lag-i-1:n-i-1] for i in range(max_lag)])
    X_restricted = add_constant(X_restricted)
    X_full = add_constant(X_full)
    try:
        rss_r = OLS(Y, X_restricted).fit().ssr
        rss_f = OLS(Y, X_full).fit().ssr
    except:
        return {'method':'perm_granger','F_obs':0,'p_value':1.0,'significant':False}
    df1 = max_lag
    df2 = len(Y) - X_full.shape[1]
    if df2 <= 0 or rss_f <= 0:
        return {'method':'perm_granger','F_obs':0,'p_value':1.0,'significant':False}
    F_obs = ((rss_r - rss_f) / df1) / (rss_f / df2)
    count = 0
    rng = np.random.RandomState(42)
    for _ in range(n_perm):
        x_perm = rng.permutation(x_ser)
        X_full_p = np.column_stack([X_restricted[:,1:]] + [x_perm[max_lag-i-1:n-i-1] for i in range(max_lag)])
