            if F_p >= F_obs: count += 1
        except:
            pass
    p = (count + 1) / (n_perm + 1)
    return {'method':'perm_granger','F_obs':round(float(F_obs),4),'p_value':round(float(p),6),'significant':bool(p < ALPHA)}

def ty_granger(c, d, cn, dn):
